  const sanitized = text.replaceAll("_", "");
  const negative = sanitized.startsWith("-");
  let digits = sanitized.replace(/^[+-]/, "");

  digits = digits.replace(/^0+(?=\d)/, "");
  if (digits === "") {
    digits = "0";
