import { parsePyFloat, parsePyInt } from "./pytypes.mjs";

export class CliExit extends Error {
  constructor(code, stream, message) {
    super(message);
    this.code = code;
    this.stream = stream;
  }
}

const OPTIONS = [
  { flag: "--a", typeName: "str", metavar: "A" },
  { flag: "--b", typeName: "int", metavar: "B" },
  { flag: "--c", typeName: "float", metavar: "C" },
];

const OPTION_MAP = new Map(OPTIONS.map((option) => [option.flag, option]));

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C\n`;
}

function buildHelp(programName) {
  return `${buildUsage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

function fail(programName, message) {
  throw new CliExit(2, "stderr", `${buildUsage(programName)}${programName}: error: ${message}\n`);
}

function parseTypedValue(option, rawValue, programName) {
  if (option.typeName === "str") {
    return rawValue;
  }

  try {
    if (option.typeName === "int") {
      return parsePyInt(rawValue);
    }

    return parsePyFloat(rawValue);
  } catch {
    fail(programName, `argument ${option.flag}: invalid ${option.typeName} value: '${rawValue}'`);
  }
}

export function getProgramName(pathValue) {
  if (!pathValue) {
    return "test10.mjs";
  }

  return pathValue.replace(/^.*[\\/]/, "");
}

export function parseTest10Args(argv, programName) {
  const values = new Map();
  const unknown = [];
  let afterDoubleDash = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (!afterDoubleDash && (token === "-h" || token === "--help")) {
      throw new CliExit(0, "stdout", buildHelp(programName));
    }

    if (!afterDoubleDash && token === "--") {
      afterDoubleDash = true;
      continue;
    }

    if (!afterDoubleDash && token.startsWith("--")) {
      const equalsIndex = token.indexOf("=");
      const flag = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const option = OPTION_MAP.get(flag);

      if (!option) {
        unknown.push(token);

        if (equalsIndex === -1 && index + 1 < argv.length && !argv[index + 1].startsWith("--")) {
          unknown.push(argv[index + 1]);
          index += 1;
        }

        continue;
      }

      let rawValue;

      if (equalsIndex !== -1) {
        rawValue = token.slice(equalsIndex + 1);
      } else {
        if (index + 1 >= argv.length || argv[index + 1].startsWith("--")) {
          fail(programName, `argument ${flag}: expected one argument`);
        }

        rawValue = argv[index + 1];
        index += 1;
      }

      values.set(flag, parseTypedValue(option, rawValue, programName));
      continue;
    }

    unknown.push(token);
  }

  const missing = OPTIONS.filter((option) => !values.has(option.flag)).map((option) => option.flag);

  if (missing.length > 0) {
    fail(programName, `the following arguments are required: ${missing.join(", ")}`);
