}

function encodeScalar(value) {
  if (value === null) {
    return "null";
  }

  if (value === true) {
    return "true";
  }

  if (value === false) {
    return "false";
  }

  if (typeof value === "string") {
    return encodeJsonString(value);
  }

  if (value instanceof PyInt) {
    return value.text;
  }

  if (value instanceof PyFloat) {
    if (!Number.isFinite(value.value)) {
      throw floatRangeError(value.value);
    }

    return value.text;
  }

  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      throw floatRangeError(value);
    }

    return formatPyFloatValue(value);
  }

  return null;
}

function isContainer(value) {
  if (value === null) {
    return false;
  }

  if (Array.isArray(value)) {
    return true;
  }

  if (value instanceof PyInt || value instanceof PyFloat) {
    return false;
  }

  return typeof value === "object";
}

function encodeCanonicalString(value) {
  return Array.from(iterencodeCanonicalParts(value)).join("");
}

function encodePrettyString(value, indentLevel = 0) {
  const scalar = encodeScalar(value);

  if (scalar !== null) {
    return scalar;
  }

  const childIndent = " ".repeat(indentLevel + 4);
  const currentIndent = " ".repeat(indentLevel);

  if (Array.isArray(value)) {
    if (value.length === 0) {
      return "[]";
    }

    const lines = value.map((item) => `${childIndent}${encodePrettyString(item, indentLevel + 4)}`);
    return `[\n${lines.join(",\n")}\n${currentIndent}]`;
  }

  if (isContainer(value)) {
    const keys = sortCanonicalKeys(Object.keys(value));

    if (keys.length === 0) {
      return "{}";
    }

    const lines = keys.map(
      (key) => `${childIndent}${encodeJsonString(key)}: ${encodePrettyString(value[key], indentLevel + 4)}`,
    );
    return `{\n${lines.join(",\n")}\n${currentIndent}}`;
  }

