}

function* iterencodeCanonicalParts(value) {
  const scalar = encodeScalar(value);

  if (scalar !== null) {
    yield scalar;
    return;
  }

  if (Array.isArray(value)) {
    if (value.length === 0) {
      yield "[]";
      return;
    }

    let prefix = "[";

    for (const item of value) {
      const itemScalar = encodeScalar(item);

      if (itemScalar !== null) {
        yield `${prefix}${itemScalar}`;
      } else {
        yield prefix;
        yield* iterencodeCanonicalParts(item);
      }

      prefix = ",";
    }

    yield "]";
    return;
  }

  if (isContainer(value)) {
    const keys = sortCanonicalKeys(Object.keys(value));

    if (keys.length === 0) {
      yield "{}";
      return;
    }

    yield "{";

    let first = true;

    for (const key of keys) {
      if (!first) {
        yield ",";
