function codePointArray(value) {
  return Array.from(value, (character) => character.codePointAt(0));
}

export function compareUnicodeStrings(left, right) {
  const leftPoints = codePointArray(left);
  const rightPoints = codePointArray(right);
  const sharedLength = Math.min(leftPoints.length, rightPoints.length);

  for (let index = 0; index < sharedLength; index += 1) {
    if (leftPoints[index] !== rightPoints[index]) {
      return leftPoints[index] - rightPoints[index];
    }
  }

  return leftPoints.length - rightPoints.length;
}

export function sortCanonicalKeys(keys) {
  return [...keys].sort(compareUnicodeStrings);
}

