function escapeByte(byteValue) {
  if (byteValue === 0x5c) {
    return "\\\\";
  }

  if (byteValue === 0x27) {
    return "\\'";
  }

  if (byteValue === 0x09) {
    return "\\t";
  }

  if (byteValue === 0x0a) {
    return "\\n";
  }

  if (byteValue === 0x0d) {
    return "\\r";
  }

  if (byteValue >= 0x20 && byteValue <= 0x7e) {
    return String.fromCharCode(byteValue);
  }

  return `\\x${byteValue.toString(16).padStart(2, "0")}`;
}

export function toPythonBytesRepr(value) {
  const buffer = Buffer.isBuffer(value) ? value : Buffer.from(value);
  let body = "";

  for (const byteValue of buffer.values()) {
    body += escapeByte(byteValue);
  }

  return `b'${body}'`;
}

